'use strict';
const grid=document.querySelector('#project-grid'),search=document.querySelector('#project-search'),dialog=document.querySelector('#project-dialog'),dialogContent=document.querySelector('#dialog-content');
let category='all',lastTrigger=null;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const status=p=>p.live?['live','Сайт']:p.demo?['prototype','Демо интерфейса']:['code','Обзор проекта'];
function renderProjects(){const query=search.value.trim().toLowerCase();const visible=PROJECTS.filter(p=>(category==='all'||p.categories.includes(category))&&[p.title,p.subtitle,p.description,...p.stack].join(' ').toLowerCase().includes(query));grid.innerHTML=visible.map(p=>{const [mode,label]=status(p);return `<article class="project-card fade-in"><button class="project-image" style="--card-bg:${p.color}" data-project="${p.id}" aria-label="Посмотреть ${escapeHTML(p.title)}"><img src="assets/${p.image}" alt="${escapeHTML(p.alt)}" loading="lazy"><span class="card-status ${mode}"><i></i>${label}</span></button><div class="card-topline"><h3>${escapeHTML(p.title)}</h3><span class="card-number">${String(PROJECTS.indexOf(p)+1).padStart(2,'0')} / ${String(PROJECTS.length).padStart(2,'0')}</span></div><p class="card-summary">${escapeHTML(p.subtitle)}</p><div class="card-meta">${p.stack.slice(0,3).map(t=>`<span class="tag">${escapeHTML(t)}</span>`).join('')}<button class="card-link" data-project="${p.id}">Смотреть проект ↗</button></div></article>`}).join('');document.querySelector('#result-summary').textContent=`ПРОЕКТЫ: ${visible.length} / ${PROJECTS.length}`;document.querySelector('#empty-state').hidden=visible.length>0;}
function openProject(id,trigger){const p=PROJECTS.find(p=>p.id===id);if(!p)return;lastTrigger=trigger;const [mode,label]=status(p);dialogContent.innerHTML=`<div class="dialog-hero" style="--card-bg:${p.color}"><img src="assets/${p.image}" alt="${escapeHTML(p.alt)}"></div><div class="dialog-body"><div class="dialog-eyebrow"><span>${escapeHTML(p.kind)}</span><span>•</span><span>${label}</span></div><h2 id="dialog-title">${escapeHTML(p.title)}</h2><p class="dialog-lead">${escapeHTML(p.description)}</p><div class="dialog-actions">${p.live?`<a class="button primary" href="${p.live}" target="_blank" rel="noopener">Открыть сайт <span>↗</span></a>`:''}${p.demo?`<a class="button ${p.live?'secondary':'primary'}" href="${p.demo}" target="_blank" rel="noopener">Попробовать демо <span>↗</span></a>`:''}${p.repo?`<a class="button secondary" href="https://github.com/Batyrkhan121/${p.repo}" target="_blank" rel="noopener">${p.private?'Репозиторий · закрытый':'Исходный код'} <span>↗</span></a>`:''}</div>${p.note?`<div class="demo-note">${escapeHTML(p.note)}</div>`:''}<div class="dialog-details"><div><h3>Что можно посмотреть</h3><ul>${p.features.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ul></div><div><h3>Технологии</h3><div class="mini-stack">${p.stack.map(x=>`<span>${escapeHTML(x)}</span>`).join('')}</div></div></div><div class="dialog-footer">${escapeHTML(p.detail||'В репозитории можно посмотреть реализацию и структуру проекта.')}</div></div>`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;history.replaceState(null,'',`#project/${p.id}`);}
function closeProject(){dialog.close();history.replaceState(null,'','#projects');lastTrigger?.focus();}
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-project]');if(trigger)openProject(trigger.dataset.project,trigger);});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{const selected=b===button;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});renderProjects();}));
search.addEventListener('input',renderProjects);document.querySelector('#dialog-close').addEventListener('click',closeProject);dialog.addEventListener('cancel',e=>{e.preventDefault();closeProject();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeProject();}});
document.querySelector('#copy-email').addEventListener('click',async()=>{const toast=document.querySelector('#toast');try{await navigator.clipboard.writeText('Batyrkk1@gmail.com');toast.textContent='Email скопирован';}catch{toast.textContent='Batyrkk1@gmail.com';}toast.hidden=false;setTimeout(()=>toast.hidden=true,3000);});
renderProjects();if(location.hash.startsWith('#project/'))openProject(decodeURIComponent(location.hash.slice(9)));
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#project/'))openProject(decodeURIComponent(location.hash.slice(9)));else if(dialog.open)dialog.close();});
